INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('watermelon-merge-strategy-game', 303236, '2024-01-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co89mo.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Watermelon Merge: Strategy Game', 'Watermelon Merge: Strategy Game is a cute and fun watermelon merging game where players combine two of the same fruits to create a larger fruit, until finally merging into a complete large watermelon. Not only does it offer classic gameplay, but also innovative modes for everyone to choose from. In the game, players earn points by merging fruits. The more consecutive merges, the higher the score. The game ends when the number of fruits on the field exceeds the limit. Additionally, there is a scoring system that ranks players globally, challenging them to achieve higher scores and stimulating their competitive desires, adding to the game''s fun and challenge.' FROM games WHERE igdb_id = 303236 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 303236 AND ge.slug = 'strategy' ON CONFLICT DO NOTHING;
