INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Raiders', 'Embark on an intergalactic journey in this adrenaline-pumping 2D space shooter! Pilot your sleek spacecraft through treacherous enemy armadas as you battle to save the galaxy from imminent destruction. With intuitive controls and fast-paced action, blast your way through wave after wave of alien invaders. Dodge incoming fire, shoot enemies in this thrilling arcade-style adventure. Are you ready to become the hero the universe desperately needs?' FROM games WHERE igdb_id = 320906 ON CONFLICT (game_id, language_code) DO NOTHING;
