INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dominions 6: Rise of the Pantokrator', 'In Dominions 6 you take control of a powerful being that rules a nation and aspires to godhood. The type of Pretender Gods can vary from magically powerful arch mages to old dragons or an enormous tree. Dominions is a deep 4x turn based strategy game with a very large variety of spells and units.' FROM games WHERE igdb_id = 260340 ON CONFLICT (game_id, language_code) DO NOTHING;
