INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flappy Octane', 'Flappy Octane is an endless level, speed increasing game. It''s game set in the future where cars can fly and all we do is pick a car and jump through rings. The rings are generated at random heights and the speed of the game increases. ​How far can you get? Can you get #1 on the leaderboards?' FROM games WHERE igdb_id = 174159 ON CONFLICT (game_id, language_code) DO NOTHING;
