INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ipad Baby', 'Alright Here Is The Description For My New Game This New Game That I''ve Been Working On Gameplay Experience And Is Trends And Topics And Assorted And News Cabin Empty Promise You I Can’t Aneurysm And Seizures Complete Constriction Of Limbs And Extremities Ambulance With Shattered Windows Marketplace Of Ideas Exiled Politician Tree With Wires Ambiguous Shape Format And Style Respectful High Risk Interactions With A Calm Disposition Mold On Bread Muffled Howl And There’s Nothing To Do But Heart Rate Crisis Width Impotent Vapid Conversation Injured By Spear Brief And Understanding Words Single Handed Arified Soaking Tarp Draped Over You Never Really Listen Virulent Soldier Common Ground My Pension Loan Apathetic Business-People Engaged In Growth And Trealistic Learning Meetings Penchant And Street Sweepstakes Important Care Don’t Free Parking For Members And One Time We Pallets Clumsily Stacked Solitary Barrier Crushed By Camp Wheel Three World Listener Purchase For Only Glass Jacket Empty Pill Bottle Soft Weeping Coming From Junk Window Beach Source But I Get Sick When I’m Around People And Cold Book Free Labor Tiled Floor' FROM games WHERE igdb_id = 282808 ON CONFLICT (game_id, language_code) DO NOTHING;
