INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soccer Bros', 'Fun, fast-paced 1 on 1 soccer game with lots of action! Pick from a variety of characters and let the play begin. Go for crazy shots, make that penalty kick, or maybe even tackle your opponent! The controls are very simple: Use either the arrow keys or wasd to control your bro. Space bar will shoot if you have the ball and tackle if you are on defense. Be sure to allow notifications so you will know when fun new soccer characters are added to the game!' FROM games WHERE igdb_id = 325227 ON CONFLICT (game_id, language_code) DO NOTHING;
