INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crimes: Open Cases', 'Crimes: Open Cases is a video game offering a series of cases that will put your skills to the test. You will have to investigate crime scenes, complete challenges to get clues, and crack the case based on the information you obtain. In addition, your prestige as an investigator is at stake. Burnish your reputation by earning more points in every challenge and shedding light on the dark secrets of each case.' FROM games WHERE igdb_id = 299858 ON CONFLICT (game_id, language_code) DO NOTHING;
