INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soda Scuffle', 'A survivor game. The items in life suddenly mutate, and you will control the soda that gains special abilities to defeat one monster after another to maintain peace. Rely on your movements to avoid enemy barrage. Pick up experience to upgrade, defeat all bosses you encounter, and you will win.' FROM games WHERE igdb_id = 290117 ON CONFLICT (game_id, language_code) DO NOTHING;
