INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gravarior', 'Gravarior is a shooting action puzzle game in which the main character, Graver, who can manipulate gravity up and down at will, tries to steal the energy hidden in the depth of a discarded ship. The ship is filled with obstacles and mysterious creatures such as Anoi. Let''s overcome the difficulties!' FROM games WHERE igdb_id = 285496 ON CONFLICT (game_id, language_code) DO NOTHING;
