INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kaiju Control Force', 'Lead a team of survivors into the abandoned Kaiju Control Force facilities, where bioengineered rats escaped and research went awry long ago, in this one-screen arcade platformer. Jump, climb and buy items from vending machines to reach the Mecha Kaiju Maintenance Bay and reclaim our city!' FROM games WHERE igdb_id = 325296 ON CONFLICT (game_id, language_code) DO NOTHING;
