INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chrono', 'Chrono is a puzzle/platformer game where you control how time affects objects in the world. By freezing time, fast-forwarding, or rewinding objects, you can crack a wide variety of puzzles. The goal is to escape the facility where you are trapped, before time runs out.' FROM games WHERE igdb_id = 306284 ON CONFLICT (game_id, language_code) DO NOTHING;
