INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heart and Core', 'A twin-stick action brawler. Young engineer JJ and her robot companion, KAI, evade the totalitarian control of the ruthless Santiago. Traverse, hide, and fight your way through a seemingly unending onslaught of enemy RAMs. Use JJ’s Gravity Gun and KAI’s fists to stun and destroy enemies.' FROM games WHERE igdb_id = 295598 ON CONFLICT (game_id, language_code) DO NOTHING;
