INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gold of Skulls', '"GOLD OF SKULLS" is a new Free-to-play, client-based collectible card game with NFT integration. It blends heroic turn-based auto-battler mechanics with rich RPG elements and deep tactical gameplay. Players will lead teams of fantastical heroes through intricate PvP and PvE battles in a world where the lines between life and death are deeply entwined.' FROM games WHERE igdb_id = 303004 ON CONFLICT (game_id, language_code) DO NOTHING;
